SELECT *
FROM t_student_attendance
WHERE lms_user_id = #{lmsUserId}
	AND delete_flg = #{deleteFlg}
ORDER BY training_date ASC

SELECT *
FROM t_student_attendance
WHERE lms_user_id = #{lmsUserId}
	AND training_date = #{trainingDate}
	AND delete_flg = #{deleteFlg}

SELECT COUNT(*) FROM t_student_attendance WHERE
lms_user_id = #{lmsUserId}
AND delete_flg = #{deleteFlg}
AND CAST(training_date AS DATE) < CAST(#{trainingDate} AS DATE)
AND status != 1 AND (
training_start_time = '' OR training_end_time = '' OR training_start_time IS NULL OR training_end_time IS NULL )

mapper.update:
UPDATE t_student_attendance
SET training_start_time = #{trainingStartTime}, training_end_time = #{trainingEndTime}, status = #{status}, note = #{note}, last_modified_user = #{lastModifiedUser}, last_modified_date = #{lastModifiedDate}, blank_time = #{blankTime}
WHERE student_attendance_id = #{studentAttendanceId}
